189	/** Activate / deactivate a mailbox (used for suspend/resume). */
190	export async function mcSetMailboxActive(address: string, active: boolean): Promise<unknown> {
191	  return mcRequest("POST", "/edit/mailbox", {
192	    items: [address],
193	    attr: { active: active ? "1" : "0" },
194	  });
195	}
