83	/**
84	 * Provision (or re-provision) a mailbox on Mailcow. Never throws — records the
85	 * outcome on the Mailbox row (status ACTIVE on success, FAILED on error) and
86	 * returns it. When Mailcow isn't configured the row is left PROVISIONING so it
87	 * can be picked up once the integration is wired.
88	 */
89	async function provisionMailboxOnMailcow(mailbox: {
90	  id: string;
91	  address: string;
92	  quotaMB: number | null;
93	  subscription: { domainName: string };
94	}): Promise<"ACTIVE" | "FAILED" | "PROVISIONING"> {
95	  if (!mailcowConfigured()) return "PROVISIONING";
96	
97	  const [localPart] = mailbox.address.split("@");
98	  const domain = mailbox.subscription.domainName;
99	  const quotaMB = mailbox.quotaMB ?? 1024;
100	
101	  try {
102	    // Ensure the mail domain exists before adding the mailbox.
103	    if (!(await mcDomainExists(domain))) {
104	      // A concurrent create or pre-existing domain can still error here; ignore
105	      // and let the mailbox add be the real signal.
106	      await mcCreateDomain(domain).catch(() => {});
107	    }
108	
109	    const password = randomBytes(18).toString("base64url");
110	    await mcCreateMailbox({
111	      localPart,
112	      domain,
113	      name: mailbox.address,
114	      password,
115	      quotaMB,
116	    });
117	
118	    await db.mailbox.update({
119	      where: { id: mailbox.id },
120	      data: { status: "ACTIVE", passwordEnc: encryptSecret(password) },
121	    });
122	    return "ACTIVE";
123	  } catch (e) {
124	    await db.mailbox
125	      .update({ where: { id: mailbox.id }, data: { status: "FAILED" } })
126	      .catch(() => {});
127	    console.warn(`[mailcow] provisioning ${mailbox.address} failed:`, e);
128	    return "FAILED";
129	  }
130	}
