593	/**
594	 * Add a mailbox to a subscription the caller owns. Enforces the plan's mailbox
595	 * quota and address uniqueness within the subscription, records the intended
596	 * mailbox (status PROVISIONING), then attempts to provision it on Mailcow. A
597	 * Mailcow failure leaves the row as FAILED (retryable) but never fails the call.
598	 */
599	export async function addMailbox(subscriptionId: string, localPart: string): Promise<Result> {
600	  const user = await requireUser();
601	
602	  const sub = await db.emailSubscription.findUnique({
603	    where: { id: subscriptionId },
604	    include: { emailPlan: true, mailboxes: true },
605	  });
606	  if (!sub) return { error: "Subscription not found." };
607	  if (sub.userId !== user.id) return { error: "Not your subscription." };
608	  if (sub.status === "CANCELLED") return { error: "This subscription is cancelled." };
609	  // SECURITY (added 2026-07-25): defence in depth against the cross-tenant
610	  // takeover fixed in subscribeEmail(). Owning the subscription ROW is not proof
611	  // of owning the DOMAIN — and because Mailcow keys mailboxes by address, any
612	  // mailbox minted here acts on that domain's real mail. An external domain must
613	  // prove control via DNS before it can mint a single address, so even if a
614	  // duplicate subscription is ever created again this cannot be weaponised.
615	  if (sub.external && !sub.verified) {
616	    return {
617	      error: "Verify this domain first — add the DNS record shown on this page, then click Verify.",
618	    };
619	  }
620	
621	  const local = String(localPart ?? "").trim().toLowerCase();
622	  if (!localPartRe.test(local) || local.length > 64) {
623	    return { error: "Enter a valid mailbox name (letters, numbers, . _ - )." };
624	  }
625	
626	  const address = `${local}@${sub.domainName}`;
627	
628	  if (sub.mailboxes.length >= sub.emailPlan.mailboxes) {
629	    return {
630	      error: `Plan limit reached (${sub.emailPlan.mailboxes} mailbox${sub.emailPlan.mailboxes === 1 ? "" : "es"}). Upgrade to add more.`,
631	    };
632	  }
633	  if (sub.mailboxes.some((m) => m.address.toLowerCase() === address)) {
634	    return { error: "That address already exists." };
635	  }
636	
637	  // Per-mailbox quota (MB) comes from the plan tier's per-mailbox storage (GB).
638	  const quotaMB = sub.emailPlan.storageGB * 1024;
639	
640	  const mailbox = await db.mailbox.create({
641	    data: { subscriptionId: sub.id, address, quotaMB, status: "PROVISIONING" },
642	  });
643	
644	  await db.auditLog.create({
645	    data: { userId: user.id, action: "mailbox.add", detail: address },
646	  });
647	
648	  // Additive, failure-tolerant provisioning — never throws out of the flow.
649	  await provisionMailboxOnMailcow({
650	    id: mailbox.id,
651	    address: mailbox.address,
652	    quotaMB,
653	    subscription: { domainName: sub.domainName },
654	  });
655	
656	  revalidatePath("/dashboard/email");
657	  return { ok: true };
658	}
