769	/**
770	 * Suspend or resume a mailbox the caller owns, mirroring the state onto Mailcow
771	 * (deactivate/activate). Owner-only, failure-tolerant on the Mailcow call.
772	 */
773	export async function setMailboxSuspended(mailboxId: string, suspended: boolean): Promise<Result> {
774	  const user = await requireUser();
775	
776	  const mailbox = await db.mailbox.findUnique({
777	    where: { id: mailboxId },
778	    include: { subscription: true },
779	  });
780	  if (!mailbox) return { error: "Mailbox not found." };
781	  if (mailbox.subscription.userId !== user.id) return { error: "Not your mailbox." };
782	
783	  // A REFUSAL means the flip did not happen on the mail server, so writing our
784	  // status to SUSPENDED/ACTIVE would be a lie the customer acts on — a "suspended"
785	  // mailbox that keeps sending and receiving, or vice versa. Only an UNREACHABLE
786	  // server is tolerated (the state will reconcile), and even then the customer is
787	  // told the mail server did not confirm.
788	  let mailcowUnreachable = false;
789	  if (mailcowConfigured()) {
790	    try {
791	      await mcSetMailboxActive(mailbox.address, !suspended);
792	    } catch (e) {
793	      if (isMailcowUnreachable(e)) {
794	        mailcowUnreachable = true;
795	        console.warn(`[mailcow] set active ${mailbox.address}: unreachable, updating local status anyway:`, e);
796	      } else {
797	        console.error(`[mailcow] set active ${mailbox.address} REFUSED:`, e);
798	        return {
799	          error: `The mail server wouldn't ${suspended ? "suspend" : "resume"} this mailbox, so nothing was changed. Please try again in a moment.`,
800	        };
801	      }
802	    }
803	  }
804	
805	  await db.mailbox.update({
806	    where: { id: mailbox.id },
807	    data: { status: suspended ? "SUSPENDED" : "ACTIVE" },
808	  });
809	
810	  await db.auditLog.create({
811	    data: {
812	      userId: user.id,
813	      action: suspended ? "mailbox.suspend" : "mailbox.resume",
814	      detail: mailbox.address,
815	    },
816	  });
817	  revalidatePath("/dashboard/email");
818	  return mailcowUnreachable
819	    ? {
820	        ok: true,
821	        warning: `Updated in your account, but the mail server was unreachable so it may not be ${suspended ? "suspended" : "active"} yet — it will reconcile when mail service is back.`,
822	      }
823	    : { ok: true };
824	}
