826	// ---------- Mailbox password (reveal / reset) ----------
827	
828	/** A strong, URL-safe mailbox password (same generator used at provisioning). */
829	function generateMailboxPassword(): string {
830	  return randomBytes(18).toString("base64url");
831	}
832	
833	/**
834	 * Reveal the stored (encrypted) password for a mailbox the caller owns, so they
835	 * can sign in to webmail. Owner-only (checked via the mailbox's subscription).
836	 * Lightly rate-limited to blunt scraping. Returns null-safe: if no password was
837	 * ever stored (e.g. Mailcow wasn't configured at provisioning) the caller is
838	 * told to reset instead. The plaintext is only ever returned to the owner.
839	 */
840	export async function revealMailboxPassword(
841	  mailboxId: string,
842	): Promise<{ error?: string; password?: string }> {
843	  const user = await requireUser();
844	
845	  const mailbox = await db.mailbox.findUnique({
846	    where: { id: mailboxId },
847	    include: { subscription: true },
848	  });
849	  if (!mailbox) return { error: "Mailbox not found." };
850	  if (mailbox.subscription.userId !== user.id) return { error: "Not your mailbox." };
851	
852	  const rl = checkRateLimit(`mailbox-pwreveal:${user.id}:${mailbox.id}`, {
853	    max: 10,
854	    windowMs: 60_000,
855	  });
856	  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };
857	
858	  const password = decryptSecret(mailbox.passwordEnc);
859	  if (!password) {
860	    return { error: "No stored password for this mailbox yet — use Reset password to set one." };
861	  }
862	  return { password };
863	}
864	
865	/**
866	 * Generate a new strong password for a mailbox the caller owns, apply it on the
867	 * mail server (Mailcow), then persist the new encrypted value. Owner-only and
868	 * rate-limited. The mail-server call must succeed before we store the new value,
869	 * so a stored password always matches what actually authenticates. Returns the
870	 * new password once for the customer to copy.
871	 */
872	export async function resetMailboxPassword(
873	  mailboxId: string,
874	): Promise<{ error?: string; password?: string }> {
875	  const user = await requireUser();
876	
877	  const mailbox = await db.mailbox.findUnique({
878	    where: { id: mailboxId },
879	    include: { subscription: true },
880	  });
881	  if (!mailbox) return { error: "Mailbox not found." };
882	  if (mailbox.subscription.userId !== user.id) return { error: "Not your mailbox." };
883	  if (!mailcowConfigured()) return { error: "Mail server is not configured yet." };
884	
885	  const rl = checkRateLimit(`mailbox-pwreset:${user.id}:${mailbox.id}`, {
886	    max: 5,
887	    windowMs: 60_000,
888	  });
889	  if (!rl.ok) return { error: `Too many resets. Try again in ${rl.retryAfterSec}s.` };
890	
891	  const password = generateMailboxPassword();
892	
893	  try {
894	    await mcSetMailboxPassword(mailbox.address, password);
895	  } catch (e) {
896	    console.warn(`[mailcow] set password ${mailbox.address} failed:`, e);
897	    return { error: "Couldn't update the password on the mail server. Try again shortly." };
898	  }
899	
900	  await db.mailbox.update({
901	    where: { id: mailbox.id },
902	    data: { passwordEnc: encryptSecret(password) },
903	  });
904	
905	  await db.auditLog.create({
906	    data: { userId: user.id, action: "mailbox.pwreset", detail: mailbox.address },
907	  });
908	  revalidatePath("/dashboard/email");
