910	}
911	
912	// ---------- Cloudflare auto-DNS (external domains) ----------
913	
914	/**
915	 * Store a customer's Cloudflare API token (encrypted) so we can create their
916	 * mail DNS records for them. The token is verified against Cloudflare before it
917	 * is saved, so we never persist a dud. requireUser + rate-limited; the token is
918	 * never logged or returned. Scope guidance (Zone → DNS → Edit) lives in the UI.
919	 */
920	export async function saveCloudflareToken(token: string): Promise<Result> {
921	  const user = await requireUser();
922	
923	  const t = String(token ?? "").trim();
924	  if (!t) return { error: "Paste your Cloudflare API token." };
925	  if (t.length < 20 || t.length > 200) {
926	    return { error: "That doesn't look like a Cloudflare API token." };
927	  }
928	
929	  const rl = checkRateLimit(`cf-token:${user.id}`, { max: 6, windowMs: 60_000 });
930	  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };
931	
932	  let valid = false;
933	  try {
934	    valid = await cfVerifyToken(t);
935	  } catch (e) {
936	    console.warn("[cloudflare] token verify failed:", e);
937	    return { error: "Couldn't reach Cloudflare to verify the token. Try again shortly." };
938	  }
939	  if (!valid) {
940	    return {
941	      error: "Cloudflare rejected that token. Check it's active and scoped to Zone → DNS → Edit.",
942	    };
943	  }
944	
945	  await db.user.update({
946	    where: { id: user.id },
947	    data: { cloudflareTokenEnc: encryptSecret(t) },
948	  });
949	  await db.auditLog.create({
950	    data: { userId: user.id, action: "cloudflare.connect", detail: "API token saved" },
951	  });
952	  revalidatePath("/dashboard/email");
953	  return { ok: true };
954	}
955	
956	/**
957	 * Auto-create the mail DNS records for an EXTERNAL email subscription in the
958	 * customer's Cloudflare zone, using their stored token. Ownership-checked and
959	 * rate-limited. Reuses getEmailDnsRecords as the single source of truth for the
960	 * record set (ownership verify TXT, MX, SPF, DKIM, DMARC), upserts each into the
961	 * zone, then leaves the existing verifyEmailDomain flow to confirm. Fails
962	 * gracefully with clear messages for invalid token / zone-not-found.
963	 */
964	export async function autoCreateEmailDns(
965	  subscriptionId: string,
966	): Promise<{ error?: string; ok?: boolean; created?: string[] }> {
967	  const user = await requireUser();
968	
969	  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
970	  if (!sub) return { error: "Subscription not found." };
971	  if (sub.userId !== user.id) return { error: "Not your subscription." };
972	  if (!sub.external) {
973	    return { error: "This domain is managed by Nxeon — no external DNS setup is needed." };
974	  }
975	
976	  const rl = checkRateLimit(`cf-autodns:${user.id}:${sub.id}`, { max: 4, windowMs: 60_000 });
977	  if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };
978	
979	  // Works for both connection shapes: OAuth credentials (refreshed here when
980	  // stale) and a legacy pasted API token. Never handles the plaintext itself.
981	  const resolved = await resolveCloudflareToken(user);
982	  const token = resolved.token;
983	  if (!token) return { error: resolved.error ?? "Connect Cloudflare first." };
984	
985	  // Same record set the customer would otherwise publish by hand.
986	  const dns = await getEmailDnsRecords(subscriptionId);
987	  if (dns.error) return { error: dns.error };
988	  const records = (dns.records ?? []).filter((r) => r.type === "MX" || r.value.trim());
989	  if (records.length === 0) {
990	    return { error: "No DNS records to create yet — try again in a moment." };
991	  }
992	
993	  // SANDBOX: never contact Cloudflare — report what we would have published so
994	  // staging can walk the whole "connect → records added" flow.
995	  if (SANDBOX) {
996	    return {
997	      ok: true,
998	      created: records.map((r) => `${r.label} (${r.type}, created)`),
999	    };
1000	  }
1001	
1002	  let zoneId: string | null;
1003	  try {
1004	    zoneId = await cfFindZoneId(token, sub.domainName);
1005	  } catch (e) {
1006	    if (e instanceof CloudflareError) {
1007	      return { error: `Cloudflare error: ${e.message}` };
1008	    }
1009	    throw e;
1010	  }
1011	  if (!zoneId) {
1012	    return {
1013	      error: `No Cloudflare zone found for ${sub.domainName}. Add the domain to Cloudflare first, or check the token is scoped to this zone.`,
1014	    };
1015	  }
1016	
1017	  let created: string[];
1018	  try {
1019	    const results = await cfUpsertRecords(
1020	      token,
1021	      zoneId,
1022	      records.map((r) => ({
1023	        type: r.type,
1024	        name: r.host,
1025	        content: r.value,
1026	        priority: r.priority,
1027	      })),
1028	    );
1029	    created = results.map((res) => {
1030	      const label = records.find((r) => r.host === res.name && r.type === res.type)?.label ?? res.name;
1031	      return `${label} (${res.type}, ${res.action})`;
1032	    });
1033	  } catch (e) {
1034	    if (e instanceof CloudflareError) {
1035	      return {
1036	        error: `Couldn't create records in Cloudflare: ${e.message}. Check the token has Zone → DNS → Edit permission.`,
1037	      };
1038	    }
1039	    throw e;
1040	  }
1041	
1042	  await db.auditLog.create({
1043	    data: {
1044	      userId: user.id,
1045	      action: "cloudflare.autodns",
1046	      detail: `${sub.domainName} — ${created.length} record(s)`,
1047	    },
1048	  });
1049	  revalidatePath("/dashboard/email");
1050	  return { ok: true, created };
1051	}
