/**
 * One-off: onboard soulpilates.com.vn as a Business Email subscription under
 * nicholas.sj.albanese@gmail.com (userId cmrztujaw0002hlazl58i3lsi) with an
 * internal "Unlimited" plan and mailboxes contact@/admin@/noreply@.
 *
 * DATA ONLY — no schema/DNS/board changes. Run with `npx tsx`, then delete.
 */
import { randomBytes } from "node:crypto";
import { db } from "../lib/db";
import { encryptSecret } from "../lib/crypto-box";
import {
  mailcowConfigured,
  mcDomainExists,
  mcCreateDomain,
  mcCreateMailbox,
  mcGetDkim,
} from "../lib/mailcow";

const USER_ID = "cmrztujaw0002hlazl58i3lsi";
const DOMAIN = "soulpilates.com.vn";
const LOCAL_PARTS = ["contact", "admin", "noreply"];
const STORAGE_GB = 25;
const QUOTA_MB = STORAGE_GB * 1024;

// DNS constants mirrored from lib/actions-email-hosting.ts (single source of truth).
const MAIL_HOST = "mail.nxeon.cloud";
const MAIL_MX_PRIORITY = 10;
const SPF_VALUE = "v=spf1 include:nxeon.cloud ~all";
const DMARC_VALUE = "v=DMARC1; p=none; rua=mailto:dmarc@nxeon.cloud";
const DKIM_SELECTOR = "dkim";

/** Strong URL-safe password, same generator family used at real provisioning. */
function genPassword(): string {
  return randomBytes(18).toString("base64url");
}

function addMonths(d: Date, months: number): Date {
  const r = new Date(d);
  r.setMonth(r.getMonth() + months);
  return r;
}

async function main() {
  const out: Record<string, unknown> = {};
  const notes: string[] = [];

  // ---- 1. Unlimited plan (create if missing) ----
  let plan = await db.emailPlan.findFirst({ where: { name: "Unlimited" } });
  if (!plan) {
    plan = await db.emailPlan.create({
      data: {
        name: "Unlimited",
        mailboxes: 9999,
        storageGB: STORAGE_GB,
        priceCents: 0,
        termMonths: 12,
        active: false,
        sortOrder: 99,
      },
    });
    notes.push(`Created Unlimited plan ${plan.id}`);
  } else {
    notes.push(`Reused existing Unlimited plan ${plan.id}`);
  }
  out.emailPlanId = plan.id;

  // ---- 2. Subscription (create or relink to Unlimited) ----
  let sub = await db.emailSubscription.findFirst({
    where: { domainName: DOMAIN, status: { not: "CANCELLED" } },
  });
  if (sub) {
    const data: Record<string, unknown> = {};
    if (sub.emailPlanId !== plan.id) data.emailPlanId = plan.id;
    if (!sub.verifyToken) data.verifyToken = randomBytes(24).toString("hex");
    if (Object.keys(data).length) {
      sub = await db.emailSubscription.update({ where: { id: sub.id }, data });
    }
    notes.push(`Reused existing subscription ${sub.id} (relinked to Unlimited)`);
  } else {
    sub = await db.emailSubscription.create({
      data: {
        userId: USER_ID,
        domainName: DOMAIN,
        emailPlanId: plan.id,
        status: "ACTIVE",
        autoRenew: true,
        external: true,
        verified: false,
        verifyToken: randomBytes(24).toString("hex"),
        expiresAt: addMonths(new Date(), 12),
      },
    });
    notes.push(`Created subscription ${sub.id}`);
  }
  out.subscriptionId = sub.id;
  out.verifyToken = sub.verifyToken;

  // ---- 3. Mailcow domain + mailboxes ----
  if (!mailcowConfigured()) {
    throw new Error("Mailcow not configured — aborting before mailbox creation.");
  }

  if (!(await mcDomainExists(DOMAIN))) {
    await mcCreateDomain(DOMAIN);
    notes.push(`Created Mailcow domain ${DOMAIN}`);
  } else {
    notes.push(`Mailcow domain ${DOMAIN} already existed`);
  }

  const mailboxOut: Array<{ address: string; password: string | null; note: string }> = [];
  for (const local of LOCAL_PARTS) {
    const address = `${local}@${DOMAIN}`;
    const existing = await db.mailbox.findUnique({ where: { address } });
    if (existing) {
      mailboxOut.push({ address, password: null, note: "SKIPPED — Mailbox row already exists" });
      continue;
    }
    const password = genPassword();
    try {
      await mcCreateMailbox({
        localPart: local,
        domain: DOMAIN,
        name: address,
        password,
        quotaMB: QUOTA_MB,
      });
    } catch (e) {
      mailboxOut.push({
        address,
        password: null,
        note: `MAILCOW FAILED: ${e instanceof Error ? e.message : String(e)}`,
      });
      continue;
    }
    await db.mailbox.create({
      data: {
        subscriptionId: sub.id,
        address,
        passwordEnc: encryptSecret(password),
        status: "ACTIVE",
        quotaMB: QUOTA_MB,
      },
    });
    mailboxOut.push({ address, password, note: "created" });
  }
  out.mailboxes = mailboxOut;

  // ---- 4. DKIM ----
  let dkimTxt: string | null = sub.dkimRecord ?? null;
  try {
    const fetched = await mcGetDkim(DOMAIN);
    if (fetched) {
      dkimTxt = fetched;
      await db.emailSubscription.update({
        where: { id: sub.id },
        data: { dkimRecord: fetched },
      });
      notes.push("Fetched + stored DKIM record");
    } else {
      notes.push("DKIM not available yet from Mailcow (null)");
    }
  } catch (e) {
    notes.push(`DKIM fetch error: ${e instanceof Error ? e.message : String(e)}`);
  }

  // ---- 5. DNS records the owner must publish ----
  out.dnsRecords = {
    ownershipTXT: {
      host: `_nxeon-verify.${DOMAIN}`,
      type: "TXT",
      value: `nxeon-verify=${sub.verifyToken ?? ""}`,
    },
    mx: { host: DOMAIN, type: "MX", value: MAIL_HOST, priority: MAIL_MX_PRIORITY },
    spf: { host: DOMAIN, type: "TXT", value: SPF_VALUE },
    dkim: {
      host: `${DKIM_SELECTOR}._domainkey.${DOMAIN}`,
      type: "TXT",
      value: dkimTxt ?? "(not generated yet — re-fetch from Mailcow)",
    },
    dmarc: { host: `_dmarc.${DOMAIN}`, type: "TXT", value: DMARC_VALUE },
  };

  out.notes = notes;
  console.log("=== RESULT_JSON_START ===");
  console.log(JSON.stringify(out, null, 2));
  console.log("=== RESULT_JSON_END ===");
}

main()
  .then(() => db.$disconnect())
  .catch(async (e) => {
    console.error("FATAL:", e);
    await db.$disconnect();
    process.exit(1);
  });

